import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"Rebrand: da \\"Nodus\\" a \\"MemoBrain Notes\\"","description":"","frontmatter":{},"headers":[],"relativePath":"release/rebrand-inventory.md","filePath":"release/rebrand-inventory.md"}'),r={name:"release/rebrand-inventory.md"};function d(n,e,s,c,l,m){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="rebrand-da-nodus-a-memobrain-notes" tabindex="-1">Rebrand: da &quot;Nodus&quot; a &quot;MemoBrain Notes&quot; <a class="header-anchor" href="#rebrand-da-nodus-a-memobrain-notes" aria-label="Permalink to &quot;Rebrand: da &quot;Nodus&quot; a &quot;MemoBrain Notes&quot;&quot;">​</a></h1><p>Il nome del prodotto è <strong>MemoBrain Notes</strong>. &quot;Nodus&quot; era il nome in codice (segnaposto) usato fino a M7. Il rename è stato eseguito prima del primo rilascio: nessuna migrazione né alias di compatibilità, perché non esistono installazioni, vault o token emessi con i nomi precedenti.</p><h2 id="convenzioni" tabindex="-1">Convenzioni <a class="header-anchor" href="#convenzioni" aria-label="Permalink to &quot;Convenzioni&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Contesto</th><th>Forma</th></tr></thead><tbody><tr><td>Nome visualizzato (UI, installer, docs, titoli)</td><td><code>MemoBrain Notes</code></td></tr><tr><td>Slug, path, chiavi, metriche, bucket, realm, client, chart, binari</td><td><code>memobrain</code> (kebab/snake/dot come prima: <code>memobrain-cloud</code>, <code>memobrain_http_requests_total</code>, <code>memobrain.web.theme</code>)</td></tr><tr><td>Variabili d&#39;ambiente</td><td><code>MEMOBRAIN_*</code></td></tr><tr><td>Identificatori Go/TS in PascalCase</td><td><code>Memobrain…</code> (es. <code>MemobrainClient</code>)</td></tr><tr><td>ID inverso dell&#39;app</td><td><code>dev.memobrain.desktop</code></td></tr><tr><td>Schema URL</td><td><code>memobrain://</code></td></tr><tr><td>Cartella di configurazione del vault</td><td><code>.memobrain/</code></td></tr><tr><td>Scope npm / modulo Go / package proto</td><td><code>@memobrain/*</code> / <code>memobrain/…</code> / <code>memobrain.v1</code></td></tr></tbody></table><p>Resta invariato il magic byte <code>NDS1</code> del formato E2EE: è un identificatore di formato, non il nome del prodotto.</p><h2 id="verifica-dei-residui" tabindex="-1">Verifica dei residui <a class="header-anchor" href="#verifica-dei-residui" aria-label="Permalink to &quot;Verifica dei residui&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/rebrand-inventory.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # conteggi del nome cercato (default: nodus); deve essere vuoto</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/rebrand-inventory.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> foo</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # cerca un altro nome</span></span></code></pre></div><p>Residui voluti: <code>Specifications.md</code> (v1.1) cita ancora &quot;Nodus&quot;, <code>.nodus/</code>, <code>nodus://</code>, <code>nodus-api</code>, ecc. e va aggiornato dall&#39;owner; gli ADR 0001–0023 usano ora il nome nuovo.</p><h2 id="fuori-perimetro-da-fare-a-parte" tabindex="-1">Fuori perimetro (da fare a parte) <a class="header-anchor" href="#fuori-perimetro-da-fare-a-parte" aria-label="Permalink to &quot;Fuori perimetro (da fare a parte)&quot;">​</a></h2><p>Logo e icone definitive, nome nello store/installer firmato e certificati di firma (il nome entra nell&#39;identità del certificato), dominio e URL pubblici (<code>memobrain.example.com</code> sono segnaposto), testi legali.</p>`,10)])])}const h=o(r,[["render",d]]);export{u as __pageData,h as default};
